-- 本番の列型・既定値・一意/検査制約を2026/11/17に読み取り専用で照合。業務データは含まない。
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE TABLE public.course_cycles (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "course_id" uuid NOT NULL,
  "cycle_no" integer NOT NULL,
  "label" text,
  "meeting_place" text,
  "meeting_time" time without time zone,
  "arrival_time" time without time zone,
  "end_time" time without time zone,
  "max_drivers" integer,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "org_id" uuid,
  CONSTRAINT "course_cycles_course_id_cycle_no_key" UNIQUE (course_id, cycle_no),
  CONSTRAINT "course_cycles_cycle_no_check" CHECK ((cycle_no >= 1)),
  CONSTRAINT "course_cycles_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.course_fixed_rate_bundles (
  "course_id" uuid NOT NULL,
  "required_cycle_nos" integer[] DEFAULT '{}'::integer[] NOT NULL,
  "fixed_revenue" numeric(12,2),
  "fixed_payout" numeric(12,2),
  "revenue_contract_amount" numeric(12,2),
  "payout_contract_amount" numeric(12,2),
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "org_id" uuid,
  CONSTRAINT "course_fixed_rate_bundles_fixed_payout_check" CHECK (((fixed_payout IS NULL) OR (fixed_payout >= (0)::numeric))),
  CONSTRAINT "course_fixed_rate_bundles_fixed_revenue_check" CHECK (((fixed_revenue IS NULL) OR (fixed_revenue >= (0)::numeric))),
  CONSTRAINT "course_fixed_rate_bundles_pkey" PRIMARY KEY (course_id)
);
CREATE TABLE public.course_fixed_rates (
  "course_id" uuid NOT NULL,
  "fixed_revenue" numeric(12,2) DEFAULT 0 NOT NULL,
  "fixed_profit" numeric(12,2) DEFAULT 0 NOT NULL,
  "fixed_payout" numeric(12,2) DEFAULT 0 NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "cycle_no" integer DEFAULT 0 NOT NULL,
  "revenue_contract_amount" numeric,
  "payout_contract_amount" numeric,
  "org_id" uuid,
  CONSTRAINT "course_fixed_rates_pkey" PRIMARY KEY (course_id, cycle_no)
);
CREATE TABLE public.course_rate_versions (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "course_id" uuid NOT NULL,
  "effective_from" date NOT NULL,
  "rate_data" jsonb NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "created_by" uuid,
  "invalid_reason" text,
  CONSTRAINT "course_rate_versions_course_id_effective_from_key" UNIQUE (course_id, effective_from),
  CONSTRAINT "course_rate_versions_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.course_report_fields (
  "course_id" uuid NOT NULL,
  "cycle_no" integer DEFAULT 0 NOT NULL,
  "unit_id" uuid NOT NULL,
  "field_key" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "org_id" uuid,
  CONSTRAINT "course_report_fields_pkey" PRIMARY KEY (course_id, cycle_no, unit_id, field_key)
);
CREATE TABLE public.course_unit_rates (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "course_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "revenue_per_unit" numeric(12,2) DEFAULT 0 NOT NULL,
  "profit_per_unit" numeric(12,2) DEFAULT 0 NOT NULL,
  "payout_per_unit" numeric(12,2) DEFAULT 0 NOT NULL,
  "fixed_revenue" integer DEFAULT 0 NOT NULL,
  "fixed_profit" integer DEFAULT 0 NOT NULL,
  "fixed_payout" integer DEFAULT 0 NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "cycle_no" integer DEFAULT 0 NOT NULL,
  "revenue_contract_amount" numeric,
  "payout_contract_amount" numeric,
  "revenue_quantity_rule" jsonb DEFAULT '{"kind": "actual"}'::jsonb NOT NULL,
  "payout_quantity_rule" jsonb DEFAULT '{"kind": "actual"}'::jsonb NOT NULL,
  "org_id" uuid,
  CONSTRAINT "course_unit_rates_course_cycle_unit_key" UNIQUE (course_id, cycle_no, unit_id),
  CONSTRAINT "course_unit_rates_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.courses (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "name" text NOT NULL,
  "color" text DEFAULT '#3b82f6'::text NOT NULL,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "max_drivers" integer DEFAULT 1 NOT NULL,
  "carrier" text DEFAULT 'OTHER'::text NOT NULL,
  "summary_title" text,
  "principal_invoice_address_id" uuid,
  "counterparty_invoice_address_id" uuid,
  "carrier_id" uuid,
  "daily_lease" integer DEFAULT 0 NOT NULL,
  "slot_id" uuid,
  "org_id" uuid NOT NULL,
  "revenue_tax_basis" text DEFAULT 'exclusive'::text NOT NULL,
  "payout_tax_basis" text DEFAULT 'exclusive'::text NOT NULL,
  "meeting_place" text,
  "meeting_time" time without time zone,
  "arrival_time" time without time zone,
  "end_time" time without time zone,
  "delivery_area" jsonb,
  "delivery_area_updated_at" timestamp with time zone,
  "delivery_area_updated_by" uuid,
  "uses_cycles" boolean DEFAULT false NOT NULL,
  "revenue_rate_mode" text DEFAULT 'PER_PIECE'::text NOT NULL,
  "payout_rate_mode" text DEFAULT 'PER_PIECE'::text NOT NULL,
  "archived_at" timestamp with time zone,
  "revenue_piece_tax_basis" text DEFAULT 'exclusive'::text NOT NULL,
  "payout_piece_tax_basis" text DEFAULT 'exclusive'::text NOT NULL,
  "revenue_fixed_tax_basis" text DEFAULT 'exclusive'::text NOT NULL,
  "payout_fixed_tax_basis" text DEFAULT 'exclusive'::text NOT NULL,
  "report_image_auto_fill" boolean DEFAULT false NOT NULL,
  CONSTRAINT "courses_carrier_check" CHECK ((carrier = ANY (ARRAY['YAMATO'::text, 'AMAZON'::text, 'OTHER'::text]))),
  CONSTRAINT "courses_name_key" UNIQUE (name),
  CONSTRAINT "courses_payout_fixed_tax_basis_check" CHECK ((payout_fixed_tax_basis = ANY (ARRAY['exclusive'::text, 'inclusive'::text]))),
  CONSTRAINT "courses_payout_piece_tax_basis_check" CHECK ((payout_piece_tax_basis = ANY (ARRAY['exclusive'::text, 'inclusive'::text]))),
  CONSTRAINT "courses_payout_rate_mode_check" CHECK ((payout_rate_mode = ANY (ARRAY['NONE'::text, 'PER_PIECE'::text, 'FIXED'::text, 'BOTH'::text]))),
  CONSTRAINT "courses_payout_tax_basis_check" CHECK ((payout_tax_basis = ANY (ARRAY['exclusive'::text, 'inclusive'::text]))),
  CONSTRAINT "courses_pkey" PRIMARY KEY (id),
  CONSTRAINT "courses_revenue_fixed_tax_basis_check" CHECK ((revenue_fixed_tax_basis = ANY (ARRAY['exclusive'::text, 'inclusive'::text]))),
  CONSTRAINT "courses_revenue_piece_tax_basis_check" CHECK ((revenue_piece_tax_basis = ANY (ARRAY['exclusive'::text, 'inclusive'::text]))),
  CONSTRAINT "courses_revenue_rate_mode_check" CHECK ((revenue_rate_mode = ANY (ARRAY['NONE'::text, 'PER_PIECE'::text, 'FIXED'::text, 'BOTH'::text]))),
  CONSTRAINT "courses_revenue_tax_basis_check" CHECK ((revenue_tax_basis = ANY (ARRAY['exclusive'::text, 'inclusive'::text])))
);
CREATE TABLE public.daily_reports_v2 (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "driver_id" uuid NOT NULL,
  "report_date" date NOT NULL,
  "course_id" uuid,
  "carrier_id" uuid,
  "identity_id" uuid,
  "vehicle_id" uuid,
  "meter_value" integer,
  "submitted_at" timestamp with time zone DEFAULT now() NOT NULL,
  "approved_at" timestamp with time zone,
  "approved_by" uuid,
  "rejected_at" timestamp with time zone,
  "rejected_by" uuid,
  "legacy_report_id" uuid,
  "org_id" uuid NOT NULL,
  "cycle_no" integer DEFAULT 0 NOT NULL,
  "rate_snapshot" jsonb,
  "rejection_reason" text,
  CONSTRAINT "daily_reports_v2_pkey" PRIMARY KEY (id),
  CONSTRAINT "daily_reports_v2_rejection_reason_check" CHECK (((rejection_reason IS NULL) OR (rejection_reason = 'shift_changed'::text)))
);
CREATE TABLE public.driver_identities (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "driver_id" uuid NOT NULL,
  "slot" smallint NOT NULL,
  "driver_code" text NOT NULL,
  "office_code" text DEFAULT ''::text NOT NULL,
  "label" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "driver_identities_driver_code_key" UNIQUE (driver_code),
  CONSTRAINT "driver_identities_driver_id_slot_key" UNIQUE (driver_id, slot),
  CONSTRAINT "driver_identities_pkey" PRIMARY KEY (id),
  CONSTRAINT "driver_identities_slot_check" CHECK ((slot = ANY (ARRAY[1, 2])))
);
CREATE TABLE public.drivers (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "name" text NOT NULL,
  "line_user_id" text,
  "role" text NOT NULL,
  "pin_hash" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "company_code" text,
  "office_code" text,
  "driver_code" text,
  "display_name" text,
  "postal_code" text,
  "address" text,
  "phone" text,
  "bank_name" text,
  "bank_no" text,
  "bank_holder" text,
  "list_no" integer,
  "license_expiry_date" date,
  "last_bonus_seen_at" timestamp with time zone,
  "org_id" uuid NOT NULL,
  "identity_id" uuid,
  "status" text DEFAULT 'active'::text NOT NULL,
  "kyc_verified_at" timestamp with time zone,
  "kyc_verified_by" uuid,
  "role_id" uuid,
  "active_from_month" text,
  "active_until_month" text,
  "works_as_driver" boolean DEFAULT false NOT NULL,
  "address_matches_license" boolean,
  "member_kind" text DEFAULT 'regular'::text NOT NULL,
  "shift_sort_order" integer,
  "token_version" integer DEFAULT 0 NOT NULL,
  "onboarding_requires_passkey" boolean DEFAULT false NOT NULL,
  "bank_branch_name" text,
  "bank_account_type" text,
  "bank_account_type_other" text,
  CONSTRAINT "drivers_active_from_month_format" CHECK (((active_from_month IS NULL) OR (active_from_month ~ '^\d{4}-\d{2}$'::text))),
  CONSTRAINT "drivers_active_until_month_format" CHECK (((active_until_month IS NULL) OR (active_until_month ~ '^\d{4}-\d{2}$'::text))),
  CONSTRAINT "drivers_bank_account_type_other_valid" CHECK ((((NOT (bank_account_type IS DISTINCT FROM 'other'::text)) AND (bank_account_type_other IS NOT NULL) AND ((length(TRIM(BOTH FROM bank_account_type_other)) >= 1) AND (length(TRIM(BOTH FROM bank_account_type_other)) <= 40)) AND (TRIM(BOTH FROM bank_account_type_other) <> 'その他'::text)) OR ((bank_account_type IS DISTINCT FROM 'other'::text) AND (bank_account_type_other IS NULL)))),
  CONSTRAINT "drivers_bank_account_type_valid" CHECK (((bank_account_type IS NULL) OR (bank_account_type = ANY (ARRAY['ordinary'::text, 'current'::text, 'savings'::text, 'other'::text])))),
  CONSTRAINT "drivers_bank_branch_name_nonempty" CHECK (((bank_branch_name IS NULL) OR (length(TRIM(BOTH FROM bank_branch_name)) > 0))),
  CONSTRAINT "drivers_line_user_id_key" UNIQUE (line_user_id),
  CONSTRAINT "drivers_member_kind_check" CHECK ((member_kind = ANY (ARRAY['regular'::text, 'guest'::text]))),
  CONSTRAINT "drivers_pkey" PRIMARY KEY (id),
  CONSTRAINT "drivers_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'rejected'::text, 'inactive'::text]))),
  CONSTRAINT "drivers_token_version_check" CHECK ((token_version >= 0))
);
CREATE TABLE public.organizations (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "admin_pin_hash" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "join_code" text,
  "status" text DEFAULT 'active'::text NOT NULL,
  "vehicle_body_colors" text[] DEFAULT '{}'::text[] NOT NULL,
  "invoice_postal_code" text,
  "invoice_address" text,
  "invoice_tel" text,
  "invoice_registration_no" text,
  "invoice_bank_name" text,
  "invoice_bank_no" text,
  "invoice_bank_holder" text,
  "invoice_stamp_path" text,
  "photo_capture_tasks" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "photo_capture_tasks_version" integer DEFAULT 1 NOT NULL,
  CONSTRAINT "companies_code_key" UNIQUE (code),
  CONSTRAINT "companies_pkey" PRIMARY KEY (id),
  CONSTRAINT "organizations_photo_capture_tasks_array_check" CHECK ((jsonb_typeof(photo_capture_tasks) = 'array'::text)),
  CONSTRAINT "organizations_photo_capture_tasks_version_check" CHECK ((photo_capture_tasks_version >= 1))
);
CREATE TABLE public.report_entries (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "report_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "field_key" text NOT NULL,
  "value_num" numeric,
  "value_text" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "org_id" uuid,
  CONSTRAINT "report_entries_pkey" PRIMARY KEY (id),
  CONSTRAINT "report_entries_report_id_unit_id_field_key_key" UNIQUE (report_id, unit_id, field_key)
);
CREATE TABLE public.role_capabilities (
  "role_id" uuid NOT NULL,
  "capability" text NOT NULL,
  CONSTRAINT "role_capabilities_pkey" PRIMARY KEY (role_id, capability)
);
CREATE TABLE public.roles (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "key" text NOT NULL,
  "label" text NOT NULL,
  "is_system" boolean DEFAULT false NOT NULL,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "works_as_driver" boolean DEFAULT false NOT NULL,
  CONSTRAINT "roles_org_id_key_key" UNIQUE (org_id, key),
  CONSTRAINT "roles_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.shift_change_logs (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid,
  "actor_driver_id" uuid,
  "action" text NOT NULL,
  "shift_date" date,
  "course_id" uuid,
  "slot" integer,
  "before" jsonb,
  "after" jsonb,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "cycle_no" integer DEFAULT 0 NOT NULL,
  CONSTRAINT "shift_change_logs_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.shifts (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "shift_date" date NOT NULL,
  "course_id" uuid NOT NULL,
  "driver_id" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "slot" integer DEFAULT 1 NOT NULL,
  "vehicle_id" uuid,
  "uses_external_vehicle" boolean DEFAULT false NOT NULL,
  "meeting_place" text,
  "meeting_time" time without time zone,
  "arrival_time" time without time zone,
  "end_time" time without time zone,
  "import_batch_id" uuid,
  "cycle_no" integer DEFAULT 0 NOT NULL,
  "org_id" uuid,
  CONSTRAINT "shifts_date_course_cycle_slot_key" UNIQUE (shift_date, course_id, cycle_no, slot),
  CONSTRAINT "shifts_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.unit_fields (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "unit_id" uuid NOT NULL,
  "field_key" text NOT NULL,
  "label" text NOT NULL,
  "input_type" text NOT NULL,
  "group_label" text,
  "is_billable" boolean DEFAULT false NOT NULL,
  "required" boolean DEFAULT false NOT NULL,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "unit_fields_input_type_check" CHECK ((input_type = ANY (ARRAY['INT'::text, 'TEXT'::text, 'TIME'::text, 'BOOL'::text]))),
  CONSTRAINT "unit_fields_pkey" PRIMARY KEY (id),
  CONSTRAINT "unit_fields_unit_id_field_key_key" UNIQUE (unit_id, field_key)
);
CREATE TABLE public.units (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "carrier_id" uuid NOT NULL,
  "name" text NOT NULL,
  "code" text,
  "billing_type" text NOT NULL,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "units_billing_type_check" CHECK ((billing_type = ANY (ARRAY['PER_PIECE'::text, 'FIXED'::text]))),
  CONSTRAINT "units_carrier_id_name_key" UNIQUE (carrier_id, name),
  CONSTRAINT "units_pkey" PRIMARY KEY (id)
);
CREATE TABLE public.vehicle_loans (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "vehicle_id" uuid NOT NULL,
  "loan_date" date NOT NULL,
  "note" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "borrower_org_id" uuid,
  CONSTRAINT "vehicle_loans_pkey" PRIMARY KEY (id),
  CONSTRAINT "vehicle_loans_vehicle_id_loan_date_key" UNIQUE (vehicle_id, loan_date)
);
CREATE TABLE public.vehicles (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "current_mileage" integer DEFAULT 0 NOT NULL,
  "last_oil_change_mileage" integer DEFAULT 0 NOT NULL,
  "oil_change_interval" integer DEFAULT 3000 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "number_prefix" text,
  "number_hiragana" text,
  "number_numeric" text,
  "purchase_cost" integer DEFAULT 0,
  "monthly_insurance" integer DEFAULT 0,
  "number_class" text,
  "manufacturer" text,
  "brand" text,
  "next_shaken_date" date,
  "lease_cost" integer DEFAULT 35000,
  "image_url" text,
  "jibaiseki_renewal_month" character(7),
  "is_disposed" boolean DEFAULT false NOT NULL,
  "purchase_cost_items" jsonb,
  "is_ev" boolean DEFAULT false NOT NULL,
  "recovery_start_month" date,
  "recovery_carryover" integer DEFAULT 0 NOT NULL,
  "owner_org_id" uuid NOT NULL,
  "image_focus_x" smallint DEFAULT 50 NOT NULL,
  "image_focus_y" smallint DEFAULT 50 NOT NULL,
  "model_key" text,
  "body_color" text,
  "model_code" text,
  "plate_color" text DEFAULT 'black'::text NOT NULL,
  "is_unavailable" boolean DEFAULT false NOT NULL,
  "unavailable_reason" text,
  "part_colors" jsonb DEFAULT '{}'::jsonb NOT NULL,
  CONSTRAINT "vehicles_image_focus_x_check" CHECK (((image_focus_x >= 0) AND (image_focus_x <= 100))),
  CONSTRAINT "vehicles_image_focus_y_check" CHECK (((image_focus_y >= 0) AND (image_focus_y <= 100))),
  CONSTRAINT "vehicles_part_colors_check" CHECK (((jsonb_typeof(part_colors) = 'object'::text) AND ((((part_colors - 'hood'::text) - 'frontBumper'::text) - 'rearBumper'::text) = '{}'::jsonb) AND ((NOT (part_colors ? 'hood'::text)) OR ((jsonb_typeof((part_colors -> 'hood'::text)) = 'string'::text) AND ((part_colors ->> 'hood'::text) ~ '^#[0-9a-fA-F]{6}$'::text))) AND ((NOT (part_colors ? 'frontBumper'::text)) OR ((jsonb_typeof((part_colors -> 'frontBumper'::text)) = 'string'::text) AND ((part_colors ->> 'frontBumper'::text) ~ '^#[0-9a-fA-F]{6}$'::text))) AND ((NOT (part_colors ? 'rearBumper'::text)) OR ((jsonb_typeof((part_colors -> 'rearBumper'::text)) = 'string'::text) AND ((part_colors ->> 'rearBumper'::text) ~ '^#[0-9a-fA-F]{6}$'::text))))),
  CONSTRAINT "vehicles_pkey" PRIMARY KEY (id),
  CONSTRAINT "vehicles_plate_color_check" CHECK ((plate_color = ANY (ARRAY['white'::text, 'yellow'::text, 'green'::text, 'black'::text]))),
  CONSTRAINT "vehicles_unavailable_reason_length_check" CHECK (((unavailable_reason IS NULL) OR (char_length(unavailable_reason) <= 120)))
);
CREATE INDEX idx_daily_reports_v2_date ON public.daily_reports_v2 USING btree (report_date);
CREATE INDEX idx_daily_reports_v2_driver ON public.daily_reports_v2 USING btree (driver_id);
CREATE INDEX idx_daily_reports_v2_carrier ON public.daily_reports_v2 USING btree (carrier_id);
CREATE UNIQUE INDEX idx_daily_reports_v2_legacy ON public.daily_reports_v2 USING btree (legacy_report_id) WHERE (legacy_report_id IS NOT NULL);
CREATE INDEX idx_daily_reports_v2_org_id ON public.daily_reports_v2 USING btree (org_id);
CREATE UNIQUE INDEX daily_reports_v2_driver_date_course_cycle_identity_key ON public.daily_reports_v2 USING btree (driver_id, report_date, course_id, cycle_no, identity_id) WHERE ((identity_id IS NOT NULL) AND (rejected_at IS NULL));
CREATE UNIQUE INDEX daily_reports_v2_driver_date_course_cycle_key ON public.daily_reports_v2 USING btree (driver_id, report_date, course_id, cycle_no) WHERE ((identity_id IS NULL) AND (rejected_at IS NULL));
CREATE TABLE public.driver_courses (
  driver_id uuid NOT NULL REFERENCES public.drivers(id),
  driver_identity_id uuid NOT NULL REFERENCES public.driver_identities(id),
  course_id uuid NOT NULL REFERENCES public.courses(id),
  cycle_no int NOT NULL DEFAULT 0,
  UNIQUE (driver_identity_id, course_id, cycle_no)
);
GRANT USAGE ON SCHEMA public TO service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;

